-- Initial PostgreSQL schema for the TypeORM-based Wildfire backend.
CREATE EXTENSION IF NOT EXISTS "pgcrypto";

CREATE TYPE "UserRole" AS ENUM ('USER','MODERATOR','ADMIN');
CREATE TYPE "UserStatus" AS ENUM ('ACTIVE','SUSPENDED','DELETED');
CREATE TYPE "AuthorVisibility" AS ENUM ('PUBLIC','ANONYMOUS');
CREATE TYPE "PublicationStatus" AS ENUM ('DRAFT','PENDING_REVIEW','PUBLISHED','HIDDEN','REMOVED');
CREATE TYPE "LifecycleStatus" AS ENUM ('NEW','DEVELOPING','ONGOING','RESOLVED');
CREATE TYPE "LocationPrecision" AS ENUM ('EXACT','LOCALITY','CITY','HIDDEN');
CREATE TYPE "MediaType" AS ENUM ('IMAGE','VIDEO','YOUTUBE');
CREATE TYPE "ReportReason" AS ENUM ('FALSE_MISLEADING','PERSONAL_INFO','THREAT_HARASSMENT','ILLEGAL_MEDIA','GRAPHIC_CONTENT','COPYRIGHT','SPAM','WRONG_CATEGORY');
CREATE TYPE "ReportStatus" AS ENUM ('OPEN','REVIEWED','DISMISSED');

CREATE TABLE "User" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"mobile" TEXT NOT NULL,"email" TEXT,"passwordHash" TEXT NOT NULL,"role" "UserRole" NOT NULL DEFAULT 'USER',"status" "UserStatus" NOT NULL DEFAULT 'ACTIVE',"isMobileVerified" BOOLEAN NOT NULL DEFAULT false,"deletedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "User_mobile_key" ON "User"("mobile"); CREATE UNIQUE INDEX "User_email_key" ON "User"("email"); CREATE INDEX "User_createdAt_idx" ON "User"("createdAt"); CREATE INDEX "User_role_status_idx" ON "User"("role","status");
CREATE TABLE "UserProfile" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"userId" UUID NOT NULL,"username" TEXT NOT NULL,"displayName" TEXT,"bio" TEXT,"avatarUrl" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "UserProfile_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "UserProfile_userId_key" ON "UserProfile"("userId"); CREATE UNIQUE INDEX "UserProfile_username_key" ON "UserProfile"("username"); CREATE INDEX "UserProfile_username_idx" ON "UserProfile"("username");
CREATE TABLE "UserSession" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"userId" UUID NOT NULL,"tokenHash" TEXT NOT NULL,"expiresAt" TIMESTAMP(3) NOT NULL,"revokedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "UserSession_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "UserSession_tokenHash_key" ON "UserSession"("tokenHash"); CREATE INDEX "UserSession_userId_idx" ON "UserSession"("userId"); CREATE INDEX "UserSession_expiresAt_idx" ON "UserSession"("expiresAt");
CREATE TABLE "PostCategory" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"value" TEXT NOT NULL,"label" TEXT NOT NULL,"description" TEXT NOT NULL,"isActive" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "PostCategory_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "PostCategory_value_key" ON "PostCategory"("value"); CREATE INDEX "PostCategory_isActive_label_idx" ON "PostCategory"("isActive","label");
CREATE TABLE "Post" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"slug" TEXT NOT NULL,"authorId" UUID NOT NULL,"categoryId" UUID NOT NULL,"title" TEXT NOT NULL,"summary" TEXT NOT NULL,"body" TEXT NOT NULL,"authorVisibility" "AuthorVisibility" NOT NULL DEFAULT 'PUBLIC',"publicationStatus" "PublicationStatus" NOT NULL DEFAULT 'DRAFT',"lifecycleStatus" "LifecycleStatus" NOT NULL DEFAULT 'NEW',"incidentDate" TIMESTAMP(3),"publishedAt" TIMESTAMP(3),"deletedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Post_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Post_slug_key" ON "Post"("slug"); CREATE INDEX "Post_publicationStatus_createdAt_idx" ON "Post"("publicationStatus","createdAt"); CREATE INDEX "Post_lifecycleStatus_createdAt_idx" ON "Post"("lifecycleStatus","createdAt"); CREATE INDEX "Post_categoryId_createdAt_idx" ON "Post"("categoryId","createdAt"); CREATE INDEX "Post_authorId_publicationStatus_authorVisibility_idx" ON "Post"("authorId","publicationStatus","authorVisibility"); CREATE INDEX "Post_deletedAt_idx" ON "Post"("deletedAt"); CREATE INDEX "Post_publishedAt_idx" ON "Post"("publishedAt");
CREATE TABLE "PostLocation" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"postId" UUID NOT NULL,"country" TEXT NOT NULL,"state" TEXT,"city" TEXT,"locality" TEXT,"latitude" DECIMAL(10,7),"longitude" DECIMAL(10,7),"precision" "LocationPrecision" NOT NULL DEFAULT 'LOCALITY',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "PostLocation_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "PostLocation_postId_key" ON "PostLocation"("postId"); CREATE INDEX "PostLocation_city_idx" ON "PostLocation"("city"); CREATE INDEX "PostLocation_state_idx" ON "PostLocation"("state"); CREATE INDEX "PostLocation_country_state_city_idx" ON "PostLocation"("country","state","city");
CREATE TABLE "PostMedia" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"postId" UUID NOT NULL,"type" "MediaType" NOT NULL,"url" TEXT NOT NULL,"thumbnailUrl" TEXT,"alt" TEXT NOT NULL,"position" INTEGER NOT NULL DEFAULT 0,"provider" TEXT,"objectKey" TEXT,"metadata" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "PostMedia_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "PostMedia_postId_position_key" ON "PostMedia"("postId","position"); CREATE INDEX "PostMedia_postId_position_idx" ON "PostMedia"("postId","position");
CREATE TABLE "PostUpdate" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"postId" UUID NOT NULL,"authorId" UUID NOT NULL,"title" TEXT NOT NULL,"content" TEXT NOT NULL,"lifecycleStatus" "LifecycleStatus" NOT NULL DEFAULT 'NEW',"deletedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "PostUpdate_pkey" PRIMARY KEY ("id")); CREATE INDEX "PostUpdate_postId_createdAt_idx" ON "PostUpdate"("postId","createdAt"); CREATE INDEX "PostUpdate_deletedAt_idx" ON "PostUpdate"("deletedAt"); CREATE INDEX "PostUpdate_authorId_idx" ON "PostUpdate"("authorId");
CREATE TABLE "PostUpdateMedia" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"postUpdateId" UUID NOT NULL,"type" "MediaType" NOT NULL,"url" TEXT NOT NULL,"thumbnailUrl" TEXT,"alt" TEXT NOT NULL,"position" INTEGER NOT NULL DEFAULT 0,"provider" TEXT,"objectKey" TEXT,"metadata" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "PostUpdateMedia_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "PostUpdateMedia_postUpdateId_position_key" ON "PostUpdateMedia"("postUpdateId","position"); CREATE INDEX "PostUpdateMedia_postUpdateId_position_idx" ON "PostUpdateMedia"("postUpdateId","position");
CREATE TABLE "Comment" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"postId" UUID NOT NULL,"authorId" UUID NOT NULL,"parentId" UUID,"content" TEXT NOT NULL,"deletedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Comment_pkey" PRIMARY KEY ("id")); CREATE INDEX "Comment_postId_createdAt_idx" ON "Comment"("postId","createdAt"); CREATE INDEX "Comment_parentId_idx" ON "Comment"("parentId"); CREATE INDEX "Comment_authorId_idx" ON "Comment"("authorId"); CREATE INDEX "Comment_deletedAt_idx" ON "Comment"("deletedAt");
CREATE TABLE "Bookmark" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"userId" UUID NOT NULL,"postId" UUID NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Bookmark_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "Bookmark_userId_postId_key" ON "Bookmark"("userId","postId"); CREATE INDEX "Bookmark_userId_createdAt_idx" ON "Bookmark"("userId","createdAt"); CREATE INDEX "Bookmark_postId_idx" ON "Bookmark"("postId");
CREATE TABLE "ContentReport" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"reporterId" UUID NOT NULL,"reviewedById" UUID,"postId" UUID,"commentId" UUID,"reason" "ReportReason" NOT NULL,"status" "ReportStatus" NOT NULL DEFAULT 'OPEN',"note" TEXT,"reviewedAt" TIMESTAMP(3),"reviewerNote" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "ContentReport_pkey" PRIMARY KEY ("id")); CREATE INDEX "ContentReport_reporterId_createdAt_idx" ON "ContentReport"("reporterId","createdAt"); CREATE INDEX "ContentReport_postId_idx" ON "ContentReport"("postId"); CREATE INDEX "ContentReport_commentId_idx" ON "ContentReport"("commentId"); CREATE INDEX "ContentReport_reviewedById_reviewedAt_idx" ON "ContentReport"("reviewedById","reviewedAt"); CREATE INDEX "ContentReport_status_createdAt_idx" ON "ContentReport"("status","createdAt");
ALTER TABLE "UserProfile" ADD CONSTRAINT "UserProfile_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "UserSession" ADD CONSTRAINT "UserSession_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Post" ADD CONSTRAINT "Post_authorId_fkey" FOREIGN KEY ("authorId") REFERENCES "User"("id") ON UPDATE CASCADE, ADD CONSTRAINT "Post_categoryId_fkey" FOREIGN KEY ("categoryId") REFERENCES "PostCategory"("id") ON UPDATE CASCADE;
ALTER TABLE "PostLocation" ADD CONSTRAINT "PostLocation_postId_fkey" FOREIGN KEY ("postId") REFERENCES "Post"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "PostMedia" ADD CONSTRAINT "PostMedia_postId_fkey" FOREIGN KEY ("postId") REFERENCES "Post"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "PostUpdate" ADD CONSTRAINT "PostUpdate_postId_fkey" FOREIGN KEY ("postId") REFERENCES "Post"("id") ON DELETE CASCADE ON UPDATE CASCADE, ADD CONSTRAINT "PostUpdate_authorId_fkey" FOREIGN KEY ("authorId") REFERENCES "User"("id") ON UPDATE CASCADE;
ALTER TABLE "PostUpdateMedia" ADD CONSTRAINT "PostUpdateMedia_postUpdateId_fkey" FOREIGN KEY ("postUpdateId") REFERENCES "PostUpdate"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Comment" ADD CONSTRAINT "Comment_postId_fkey" FOREIGN KEY ("postId") REFERENCES "Post"("id") ON DELETE CASCADE ON UPDATE CASCADE, ADD CONSTRAINT "Comment_authorId_fkey" FOREIGN KEY ("authorId") REFERENCES "User"("id") ON UPDATE CASCADE, ADD CONSTRAINT "Comment_parentId_fkey" FOREIGN KEY ("parentId") REFERENCES "Comment"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "Bookmark" ADD CONSTRAINT "Bookmark_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE, ADD CONSTRAINT "Bookmark_postId_fkey" FOREIGN KEY ("postId") REFERENCES "Post"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ContentReport" ADD CONSTRAINT "ContentReport_reporterId_fkey" FOREIGN KEY ("reporterId") REFERENCES "User"("id") ON UPDATE CASCADE, ADD CONSTRAINT "ContentReport_reviewedById_fkey" FOREIGN KEY ("reviewedById") REFERENCES "User"("id") ON UPDATE CASCADE, ADD CONSTRAINT "ContentReport_postId_fkey" FOREIGN KEY ("postId") REFERENCES "Post"("id") ON DELETE CASCADE ON UPDATE CASCADE, ADD CONSTRAINT "ContentReport_commentId_fkey" FOREIGN KEY ("commentId") REFERENCES "Comment"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ContentReport" ADD CONSTRAINT "ContentReport_exactly_one_target" CHECK (("postId" IS NOT NULL AND "commentId" IS NULL) OR ("postId" IS NULL AND "commentId" IS NOT NULL));
CREATE UNIQUE INDEX "ContentReport_open_post_unique" ON "ContentReport"("reporterId","postId") WHERE "status"='OPEN' AND "postId" IS NOT NULL;
CREATE UNIQUE INDEX "ContentReport_open_comment_unique" ON "ContentReport"("reporterId","commentId") WHERE "status"='OPEN' AND "commentId" IS NOT NULL;
